-- ----------------------------
-- Table structure for Kategoris
-- ----------------------------
DROP TABLE IF EXISTS `Kategoris`;
CREATE TABLE `Kategoris`  (
  `IDKategori` int NOT NULL AUTO_INCREMENT,
  `NamaKategori_ID` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `NamaKategori_EN` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  PRIMARY KEY (`IDKategori`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of Kategoris
-- ----------------------------
INSERT INTO `Kategoris` VALUES (1, 'Ekonomi', 'Economy');
INSERT INTO `Kategoris` VALUES (2, 'Asuransi', 'Insurance');
INSERT INTO `Kategoris` VALUES (3, 'Perumahan', 'Residential');
INSERT INTO `Kategoris` VALUES (4, 'Komersial', 'Commercial');

-- ----------------------------
-- Table structure for News
-- ----------------------------
DROP TABLE IF EXISTS `News`;
CREATE TABLE `News`  (
  `IDNews` int NOT NULL AUTO_INCREMENT,
  `UrlGambar` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `Judul_ID` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `Judul_EN` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `IsiContent_ID` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `IsiContent_EN` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `CreateAt` datetime(6) NOT NULL,
  `IsSent` tinyint(1) NOT NULL,
  `IDKategori` int NOT NULL,
  PRIMARY KEY (`IDNews`) USING BTREE,
  INDEX `IX_News_IDKategori`(`IDKategori` ASC) USING BTREE,
  CONSTRAINT `FK_News_Kategoris_IDKategori` FOREIGN KEY (`IDKategori`) REFERENCES `Kategoris` (`IDKategori`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

