-- ----------------------------
-- Table structure for Portfolios
-- ----------------------------
DROP TABLE IF EXISTS `Portfolios`;
CREATE TABLE `Portfolios`  (
  `IDPortfolio` int NOT NULL AUTO_INCREMENT,
  `UrlGambar` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `Judul_ID` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `Judul_EN` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `IsiContentPortfolio_ID` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `IsiContentPortfolio_EN` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `ClientComment_ID` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `ClientComment_EN` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `CreateAt` datetime(6) NOT NULL,
  `ClientName` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `ClientCompanyName` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `ProjectStartDate` datetime(6) NOT NULL,
  `ProjectEndDate` datetime(6) NOT NULL,
  PRIMARY KEY (`IDPortfolio`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

