-- ----------------------------
-- Table structure for Pricings
-- ----------------------------
DROP TABLE IF EXISTS `Pricings`;
CREATE TABLE `Pricings`  (
  `IDPricing` int NOT NULL AUTO_INCREMENT,
  `JenisLayanan_ID` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `JenisLayanan_EN` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `DeskripsiJenisLayanan_ID` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `DeskripsiJenisLayanan_EN` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `Harga` double NULL DEFAULT NULL,
  `CreateAt` datetime(6) NOT NULL,
  PRIMARY KEY (`IDPricing`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

