-- ----------------------------
-- Table structure for Teams
-- ----------------------------
DROP TABLE IF EXISTS `Teams`;
CREATE TABLE `Teams`  (
  `IDTeam` int NOT NULL AUTO_INCREMENT,
  `UrlFoto` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `Email` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `NoHP` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `Website` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `Nama` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `UrlFb` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `UrlLinkedIn` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `UrlYoutube` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `UrlTwiter` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `Jabatan_ID` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `Jabatan_EN` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `Deskripsi_ID` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `Deskripsi_EN` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
